package com.example.shop.checkout.core.application;

import com.example.shop.order.core.application.OrderService;
import com.example.shop.order.core.application.PlaceOrder;
import io.domainlifecycles.domain.types.ApplicationService;

public class CheckoutService implements ApplicationService {
    private final OrderService orderService;
    public CheckoutService(OrderService orderService) { this.orderService = orderService; }
    public void checkout(Long customerId) { orderService.place(new PlaceOrder(customerId)); }
    public void quickBuy(Long customerId) { orderService.place(customerId, 1); }
}

