package com.example.shop.order.core.domain;

import io.domainlifecycles.domain.types.Identity;
import io.domainlifecycles.domain.types.base.AggregateRootBase;

public final class Customer extends AggregateRootBase<Customer.CustomerId> {
    public record CustomerId(Long value) implements Identity<Long> {}
    private final CustomerId id;
    private final String name;

    public Customer(long concurrencyVersion, CustomerId id, String name) {
        super(concurrencyVersion);
        this.id = id;
        this.name = name;
    }

    @Override public CustomerId getId() { return id; }
}

